abstract class OrderBuilder<B extends OrderBuilder<B>> {
    protected int grams;
    protected String variety;

    B grams(int grams) { this.grams = grams; return self(); }
    B variety(String name) { this.variety = name; return self(); }
    protected abstract B self();
}

final class GiftBoxBuilder extends OrderBuilder<GiftBoxBuilder> {
    private String ribbon;

    GiftBoxBuilder ribbon(String colour) { this.ribbon = colour; return this; }
    @Override protected GiftBoxBuilder self() { return this; }

    GiftBox build() {
        if (grams <= 0) throw new IllegalStateException("weight must be positive");
        return new GiftBox(grams, variety, "", ribbon);
    }
}

